//! `graphic` — Frame Job's motion-graphics engine (road map 10 §5a). Its
//! drawing half: the font and asset Library, `rasterize` (usvg parse →
//! resvg render → premultiplied BGRA), `measure_text`, and the Diagnostic.
//! Its JavaScript half: a `Module` compiled once, and `svg`, which runs its
//! `render` in a sandboxed QuickJS engine per (thread, module) (§5b, §5c).
//! The crate takes bytes and answers bytes: no file system, environment or
//! network, and no clock but the call deadline in `runtime.rs` (G-2, G-5).
//!
//! Declarations and re-exports only — no implementation lives here.

#![forbid(unsafe_code)]

mod diagnostic;
mod exception;
mod host;
mod images;
mod library;
mod measure;
mod module;
mod props;
mod raster;
mod runtime;
mod sandbox;

pub use diagnostic::{Diagnostic, Level};
pub use images::{
    image_cache_builds, image_cache_bytes, set_image_build_hook, set_image_cache_limit,
    ImageBuildHook,
};
pub use library::{Face, Library};
pub use measure::{measure_text, FontStyle, TextFont, TextMetrics};
pub use module::Module;
pub use props::{overlay, MAX_OPTIONS, MAX_PROPS, MAX_STRING, TYPES};
pub use raster::{rasterize, MAX_SIDE};
pub use runtime::{engine_count, svg, ENGINES_PER_THREAD, HEAP_BYTES, STACK_BYTES, SVG_BYTES};
//! The one non-oracle (road map 10 §5l): the SHA-256 of the BGRA of frames
//! 0, 30 and 90 of each fixture, pinned in `tests/pins.json`. A tripwire
//! for a resvg or QuickJS upgrade, not a correctness claim. On a mismatch
//! the frames are written to `target/pins/` to look at;
//! `GRAPHIC_REPIN=1` rewrites the file.

mod common;

use std::fs;

use graphic::rasterize;
use serde_json::{Map, Value};

use common::{shared, FIXTURES};

const PINS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/pins.json");
const DUMP: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/target/pins");
const FRAMES: [i64; 3] = [0, 30, 90];

fn bgra(name: &str, frame: i64) -> Vec<u8> {
    let module = common::module(name);
    let (svg, _) =
        common::frame(&module, frame).unwrap_or_else(|d| panic!("{name} {frame}: {}", d.message));
    let mut out = vec![0u8; 1920 * 1080 * 4];
    rasterize(&shared(), &svg, 1920, 1080, &mut out, 1920 * 4)
        .unwrap_or_else(|d| panic!("{name} {frame}: {}", d.message));
    out
}

/// The frame as an RGBA PNG (still premultiplied: for a person to look at).
fn dump(name: &str, frame: i64, bgra: &[u8]) {
    fs::create_dir_all(DUMP).expect("target/pins");
    let rgba: Vec<u8> = bgra
        .chunks_exact(4)
        .flat_map(|p| [p[2], p[1], p[0], p[3]])
        .collect();
    let file = fs::File::create(format!("{DUMP}/{name}-{frame}.png")).expect("a PNG file");
    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), 1920, 1080);
    encoder.set_color(png::ColorType::Rgba);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder.write_header().expect("a PNG header");
    writer.write_image_data(&rgba).expect("PNG data");
}

#[test]
fn the_fixtures_frames_match_their_pins() {
    let mut current = Map::new();
    for name in FIXTURES {
        let mut frames = Map::new();
        for frame in FRAMES {
            let bytes = bgra(name, frame);
            frames.insert(frame.to_string(), Value::from(common::sha256(&bytes)));
            if std::env::var("GRAPHIC_REPIN").is_err() {
                let pins: Value =
                    serde_json::from_str(&fs::read_to_string(PINS).expect("tests/pins.json"))
                        .expect("pins.json is JSON");
                if pins[name][frame.to_string()] != frames[&frame.to_string()] {
                    for f in FRAMES {
                        dump(name, f, &bgra(name, f));
                    }
                    panic!(
                        "{name} frame {frame}: the rasterizer's output changed — if this is a resvg upgrade, re-pin after looking at the PNGs in target/pins/"
                    );
                }
            }
        }
        current.insert(name.to_string(), Value::Object(frames));
    }
    if std::env::var("GRAPHIC_REPIN").is_ok() {
        let text = serde_json::to_string_pretty(&Value::Object(current)).unwrap() + "\n";
        fs::write(PINS, text).expect("tests/pins.json written");
    }
}
//! `svg` (road map 10 §5b): the six fixtures draw cleanly, and every way
//! `render` can answer wrongly is named, with the frame, and with the
//! module's own line when it threw.

mod common;

use graphic::{rasterize, Diagnostic, Module, SVG_BYTES};

use common::{shared, BUDGET_MS, FIXTURES};

fn compile(source: &str) -> Module {
    Module::compile(shared(), "probe", source, BUDGET_MS)
        .unwrap_or_else(|d| panic!("did not compile: {}", d.message))
}

fn failure(source: &str, frame: i64) -> Diagnostic {
    let module = compile(source);
    let ctx = common::ctx(frame, 30.0, 150, 1920, 1080);
    match graphic::svg(&module, frame, &serde_json::json!({}), &ctx, BUDGET_MS) {
        Ok((svg, _)) => panic!("drew, and should not have: {svg:.120}"),
        Err(d) => d,
    }
}

#[test]
fn the_six_fixtures_draw_without_a_warning() {
    for name in FIXTURES {
        let module = common::module(name);
        for frame in [0, 30, 90] {
            let (svg, warnings) =
                common::frame(&module, frame).unwrap_or_else(|d| panic!("{name} {frame}: {d:?}"));
            assert!(svg.starts_with("<svg"), "{name} {frame}");
            assert!(warnings.is_empty(), "{name} {frame}: {warnings:?}");
            let mut out = vec![0u8; 1920 * 1080 * 4];
            let raster = rasterize(&shared(), &svg, 1920, 1080, &mut out, 1920 * 4)
                .unwrap_or_else(|d| panic!("{name} {frame}: {}", d.message));
            assert!(raster.is_empty(), "{name} {frame}: {raster:?}");
        }
    }
}

#[test]
fn a_number_is_named() {
    let d = failure(
        "export function render(frame, props, ctx) { return 42; }",
        7,
    );
    assert_eq!(
        d.message,
        "render returned number at frame 7; it must return an SVG string"
    );
    assert_eq!(d.frame, Some(7));
    assert_eq!((d.line, d.column), (None, None));
}

#[test]
fn a_string_that_is_not_svg_is_quoted() {
    let d = failure(
        "export function render(frame, props, ctx) { return \"<div>\"; }",
        3,
    );
    assert_eq!(
        d.message,
        "render returned a string that does not start with <svg at frame 3: \"<div>\""
    );
    assert_eq!(d.frame, Some(3));
}

fn of_length(length: usize) -> String {
    format!(
        "export function render(frame, props, ctx) {{ return \"<svg\" + \"x\".repeat({}); }}",
        length - 4
    )
}

#[test]
fn an_svg_over_the_cap_is_refused_with_its_length() {
    let d = failure(&of_length(SVG_BYTES + 1), 0);
    assert_eq!(
        d.message,
