                    );
                }
            }
        }
        current.insert(name.to_string(), Value::Object(frames));
    }
    if std::env::var("GRAPHIC_REPIN").is_ok() {
        let text = serde_json::to_string_pretty(&Value::Object(current)).unwrap() + "\n";
        fs::write(PINS, text).expect("tests/pins.json written");
    }
}
