        .filter(|stem| !FIXTURES.contains(&stem.as_str()))
        .collect();
    stems.sort();
    assert!(!stems.is_empty(), "no template in {GRAPHICS}");
    stems
}

fn duration(module: &Module) -> i64 {
    module.meta()["durationInFrames"]
        .as_i64()
        .expect("a template's meta.durationInFrames")
}

/// One frame drawn: the BGRA, or every problem with it named.
fn draw(
    module: &Module,
    frame: i64,
    props: &Value,
    (width, height): (u32, u32),
) -> Result<Vec<u8>, String> {
    let name = module.name();
    let ctx = common::ctx(frame, FPS, duration(module), width, height);
    let at = format!("{name} {width}x{height} frame {frame}");
    let (svg, warnings) = graphic::svg(module, frame, props, &ctx, BUDGET_MS)
        .map_err(|d| format!("{at}: {}", d.message))?;
    if !warnings.is_empty() {
        return Err(format!("{at}: svg warned {:?}", common::messages(&warnings)));
    }
    for bad in ["NaN", "Infinity"] {
        if svg.contains(bad) {
            return Err(format!("{at}: the SVG holds {bad}"));
        }
    }
    let stride = width as usize * 4;
    let mut out = vec![0u8; stride * height as usize];
    let raster = rasterize(&shared(), &svg, width, height, &mut out, stride)
        .map_err(|d| format!("{at}: rasterize refused: {}", d.message))?;
    if !raster.is_empty() {
        return Err(format!(
            "{at}: rasterize warned {:?}",
            common::messages(&raster)
        ));
    }
    Ok(out)
}

/// Whether pixel `(x, y)` is outside title-safe: x ∈ [0.05W, 0.95W),
/// y ∈ [0.05H, 0.95H).
fn outside(x: u32, y: u32, (width, height): (u32, u32)) -> bool {
    x < width * 5 / 100 || x >= width * 95 / 100 || y < height * 5 / 100 || y >= height * 95 / 100
}

/// The first pixel outside title-safe where `a` and `b` differ.
fn first_difference(a: &[u8], b: &[u8], size: (u32, u32)) -> Option<(u32, u32)> {
    let (width, height) = size;
    for y in 0..height {
        for x in 0..width {
            let at = (y as usize * width as usize + x as usize) * 4;
            if outside(x, y, size) && a[at..at + 4] != b[at..at + 4] {
                return Some((x, y));
            }
        }
    }
    None
}

/// Frame 0's alpha outside title-safe, when it is one value (0 or 255).
fn border_alpha(frame0: &[u8], size: (u32, u32)) -> Result<u8, String> {
    let (width, height) = size;
    let mut seen: Option<u8> = None;
    for y in 0..height {
        for x in 0..width {
            if !outside(x, y, size) {
                continue;
            }
            let alpha = frame0[(y as usize * width as usize + x as usize) * 4 + 3];
            match seen {
                None => seen = Some(alpha),
                Some(a) if a != alpha => {
                    return Err(format!("alpha {a} and {alpha} (at {x},{y}) outside title-safe"))
                }
                _ => {}
            }
        }
    }
    match seen {
        Some(a @ (0 | 255)) => Ok(a),
        other => Err(format!("alpha {other:?} outside title-safe, not 0 or 255")),
    }
}

/// Writes `frame` of `module` at `size` over opaque `#6e6e74` as an RGB PNG.
fn dump(dir: &str, module: &Module, frame: i64, size: (u32, u32)) {
    let (width, height) = size;
    let bgra = draw(module, frame, &module.defaults(), size).unwrap_or_else(|e| panic!("{e}"));
    let grey = [0x6e_u32, 0x6e, 0x74];
    let rgb: Vec<u8> = bgra
        .chunks_exact(4)
        .flat_map(|p| {
            let under = 255 - p[3] as u32;
            let over = |src: u8, bg: u32| (src as u32 + (bg * under + 127) / 255).min(255) as u8;
            [over(p[2], grey[0]), over(p[1], grey[1]), over(p[0], grey[2])]
        })
        .collect();
    fs::create_dir_all(dir).expect("the PNG folder");
    let path = format!("{dir}/{}-{width}x{height}-{frame}.png", module.name());
    let file = fs::File::create(&path).expect("a PNG file");
    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), width, height);
    encoder.set_color(png::ColorType::Rgb);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder.write_header().expect("a PNG header");
    writer.write_image_data(&rgb).expect("PNG data");
}

/// The frames sampled: 0, 5, 10, … and the last.
fn sampled(duration: i64) -> Vec<i64> {
    let mut frames: Vec<i64> = (0..duration).step_by(5).collect();
    if frames.last() != Some(&(duration - 1)) {
        frames.push(duration - 1);
    }
    frames
}

#[test]
fn every_template_draws_cleanly_inside_title_safe() {
    let dump_dir = std::env::var("GRAPHIC_TEMPLATE_PNGS").ok();
    let mut failures = Vec::new();
    for stem in templates() {
        let module = common::module(&stem);
        let props = module.defaults();
        let d = duration(&module);
        for size in SIZES {
            let mut times = Vec::new();
            let mut frame0: Option<Vec<u8>> = None;
            for frame in sampled(d) {
                let started = Instant::now();
                let drawn = draw(&module, frame, &props, size);
                times.push(started.elapsed().as_secs_f64() * 1000.0);
                let bgra = match drawn {
                    Ok(bgra) => bgra,
                    Err(e) => {
                        failures.push(e);
                        continue;
                    }
                };
                match &frame0 {
                    None => {
                        if let Err(e) = border_alpha(&bgra, size) {
                            failures.push(format!("{stem} {size:?} frame 0: {e}"));
                        }
                        frame0 = Some(bgra);
                    }
                    Some(first) => {
                        if let Some((x, y)) = first_difference(first, &bgra, size) {
                            failures.push(format!(
                                "{stem} {size:?} frame {frame}: pixel ({x}, {y}) outside title-safe differs from frame 0"
                            ));
                        }
                    }
                }
            }
            if size == SIZES[0] {
                times.sort_by(|a, b| a.partial_cmp(b).unwrap());
                let p95 = times[((times.len() as f64 * 0.95).ceil() as usize).max(1) - 1];
                println!("{stem}: p95 svg+rasterize {p95:.2} ms at 1920x1080");
            }
            if let Some(dir) = &dump_dir {
                for frame in [12, d / 2, d - 8] {
                    dump(dir, &module, frame, size);
                }
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn degenerate_props_draw_cleanly() {
    let cases = [
        ("line-chart", serde_json::json!({"values": "5"})),
        ("donut-chart", serde_json::json!({"values": "0, 0"})),
        ("gauge", serde_json::json!({"min": 0, "max": 0, "value": 0})),
    ];
    let mut failures = Vec::new();
    for (stem, overrides) in cases {
        let module = common::module(stem);
        let mut props = module.defaults();
        for (key, value) in overrides.as_object().unwrap() {
            props[key] = value.clone();
        }
        let d = duration(&module);
        for size in SIZES {
            for frame in [0, d / 2, d - 1] {
                if let Err(e) = draw(&module, frame, &props, size) {
                    failures.push(e);
                }
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// The file names listed under `key:` in the "Copy Graphic Templates" phase.
fn listed(phase: &str, key: &str) -> Vec<String> {
    let mut names: Vec<String> = phase
        .lines()
        .skip_while(|line| line.trim() != format!("{key}:"))
        .skip(1)
        .take_while(|line| line.trim_start().starts_with("- "))
        .map(|line| line.rsplit('/').next().unwrap().trim().to_string())
        .collect();
    names.sort();
    names
}

#[test]
fn project_yml_lists_every_template() {
    let yml = fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../project.yml"))
        .expect("project.yml");
    let start = yml
        .find("- name: Copy Graphic Templates")
        .expect("the Copy Graphic Templates phase");
    let rest = &yml[start + 1..];
    let phase = &rest[..rest.find("- name:").unwrap_or(rest.len())];
    let mut files: Vec<String> = fs::read_dir(GRAPHICS)
        .expect("tests/graphics")
        .map(|entry| entry.expect("a directory entry").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "js"))
        .map(|path| path.file_name().unwrap().to_string_lossy().into_owned())
        .collect();
    files.sort();
    assert_eq!(listed(phase, "inputFiles"), files, "inputFiles");
    assert_eq!(listed(phase, "outputFiles"), files, "outputFiles");
}

// line-chart — a bundled template (spec §11 G-44): `values` as a
// comma-separated string, a line drawn on through its points, a dot popping
// at each, an area fill behind and the last value called out.
export const meta = {
  name: "Line chart",
  durationInFrames: 150,
};

export const schema = {
  values: { type: "string",  default: "12, 18, 15, 26, 22, 34, 41", animate: false },
  labels: { type: "string",  default: "Jan, Feb, Mar, Apr, May, Jun, Jul", animate: false },
  title:  { type: "string",  default: "Monthly active users" },
  area:   { type: "boolean", default: true },
  accent: { type: "color",   default: "#2d7ff9" },
};

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const D = ctx.durationInFrames;
  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => v !== "" && isFinite(v));
  const labels = props.labels.split(",").map((l) => l.trim());
  const n = values.length;
  const safeX = ctx.width * 0.05;
  const safeY = ctx.height * 0.05;
  const safeW = ctx.width * 0.9;
  const safeH = ctx.height * 0.9;
  const pad = 60 * u;
  const innerW = safeW - 2 * pad;
  const blockH = Math.min(safeH - 2 * pad, innerW * 1.1);
  const top = safeY + (safeH - blockH) / 2;
  const titleFont = { family: "Montserrat", weight: 900 };
  const titleSize = fitText(props.title, innerW, titleFont, { min: 12 * u, max: 64 * u });
  const left = safeX + pad;
  const right = left + innerW;
  const plotTop = top + titleSize + 110 * u;
  const base = top + blockH - 64 * u;
  const lo = Math.min(0, ...values);
  const hi = Math.max(lo + 1, ...values);
  const span = Math.max(1e-9, hi - lo);
  const points = values.map((v, i) => ({
    x: n === 1 ? (left + right) / 2 : left + (innerW * i) / Math.max(1, n - 1),
    y: base - ((v - lo) / span) * (base - plotTop),
  }));
  const fade = interpolate(frame, [0, 15], [0, 1], { clamp: true });
  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
  const ease = (f) => interpolate(f, [10, 70], [0, 1], { easing: Easing.inOutCubic, clamp: true });
  const drawn = ease(frame);

  let grid = "";
  for (let i = 0; i <= 4; i++) {
    const y = base - ((base - plotTop) * i) / 4;
    grid += `<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#ffffff"
                   stroke-opacity="${i === 0 ? 0.35 : 0.08}" stroke-width="${(i === 0 ? 3 : 2) * u}"/>`;
  }
  let axisLabels = "";
  points.forEach((p, i) => {
    const anchor = n > 1 && i === 0 ? "start" : n > 1 && i === n - 1 ? "end" : "middle";
    axisLabels += `<text x="${p.x}" y="${base + 46 * u}" text-anchor="${anchor}" font-family="Montserrat"
                         font-weight="800" font-size="${28 * u}" fill="#c8c8d0">${escapeXml(labels[i] || "")}</text>`;
  });

  let line = "";
  let areaFill = "";
  const reach = [0];
  if (n > 1) {
    let d = `M ${points[0].x} ${points[0].y}`;
    let total = 0;
    for (let i = 1; i < n; i++) {
      const a = points[i - 1];
      const b = points[i];
      const mid = (a.x + b.x) / 2;
      const seg = `C ${mid} ${a.y} ${mid} ${b.y} ${b.x} ${b.y}`;
      total += getLength(`M ${a.x} ${a.y} ${seg}`);
      reach.push(total);
      d += ` ${seg}`;
    }
    const dash = evolvePath(drawn, d);
    const tip = getPointAtLength(d, getLength(d) * drawn);
    line = `<path d="${d}" fill="none" stroke="${props.accent}" stroke-width="${7 * u}" stroke-linecap="round"
                  stroke-linejoin="round" stroke-dasharray="${dash.strokeDasharray}"
                  stroke-dashoffset="${dash.strokeDashoffset}"/>`;
    if (props.area) {
      areaFill = `<clipPath id="reveal"><rect x="${left - 10 * u}" y="${plotTop - 40 * u}"
                    width="${Math.max(0, tip.x - left + 10 * u)}" height="${base - plotTop + 40 * u}"/></clipPath>
        <path d="${d} L ${points[n - 1].x} ${base} L ${points[0].x} ${base} Z" fill="url(#areaGrad)"
              clip-path="url(#reveal)" opacity="${interpolate(frame, [14, 50], [0, 1], { clamp: true })}"/>`;
    }
    for (let i = 0; i < n; i++) reach[i] = reach[i] / Math.max(1e-9, total);
  }
  // The frame at which the line reaches point i: the first frame whose eased progress passes it.
  const reachFrame = (fraction) => {
    for (let f = 10; f <= 70; f++) if (ease(f) >= fraction - 1e-6) return f;
    return 70;
  };
  let dots = "";
  points.forEach((p, i) => {
    const at = n > 1 ? reachFrame(reach[i]) : 14;
    const s = spring({ frame: frame - at, fps: ctx.fps, stiffness: 220, damping: 11 });
    if (s <= 0.001) return;
    dots += `<circle cx="${p.x}" cy="${p.y}" r="${11 * u * s}" fill="#15151b" stroke="${props.accent}"
                     stroke-width="${5 * u}"/>`;
  });
  let callout = "";
  if (n > 0) {
    const last = points[n - 1];
    const at = (n > 1 ? reachFrame(1) : 14) + 4;
    const s = spring({ frame: frame - at, fps: ctx.fps, stiffness: 180, damping: 12 });
    const text = formatNumber(values[n - 1], { decimals: Number.isInteger(values[n - 1]) ? 0 : 1 });
    const font = { family: "Montserrat", size: 34 * u, weight: 800 };
    const w = measureText(text, font).width + 36 * u;
    const h = 54 * u;
    const cx = Math.min(right - w / 2, Math.max(left + w / 2, last.x));
    const cy = last.y - 30 * u - h / 2;
    if (s > 0.001) {
      callout = `<g transform="translate(${cx} ${cy}) scale(${s})">
        <rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="${h / 2}" fill="${props.accent}"/>
        <text x="0" y="${12 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800"
              font-size="${font.size}" fill="#ffffff">${escapeXml(text)}</text></g>`;
    }
  }
  return svg(ctx, `
    <defs>
      <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="${props.accent}" stop-opacity="0.35"/>
        <stop offset="1" stop-color="${props.accent}" stop-opacity="0.02"/>
      </linearGradient>
    </defs>
    <g opacity="${out}">
      <g opacity="${fade}">
        <text x="${left}" y="${top + titleSize * 0.8}" font-family="Montserrat" font-weight="900"
              font-size="${titleSize}" fill="#ffffff">${escapeXml(props.title)}</text>
        ${grid}${axisLabels}
      </g>
      ${areaFill}${line}${dots}${callout}
    </g>`, { background: "#15151b" });
}

