  const bulletGap = 34 * u;
  const bulletR = 7 * u;
  const widths = items.map((s) => measureText(s, itemFont).width);
  const cycle = widths.reduce((a, w) => a + w + 2 * bulletGap, 0);
  const crawlLeft = x0 + headW;
  const crawlRight = x0 + bandW;
  const baseline = y + bandH / 2 + itemFont.size * 0.36;
  let crawl = "";
  if (items.length > 0 && cycle > 0) {
    const offset = props.speed * u * Math.max(0, ctx.time);
    let start = crawlRight - offset;
    if (start < crawlLeft - cycle) start += Math.floor((crawlLeft - start) / cycle - 1) * cycle;
    for (let k = 0; start + k * cycle < crawlRight; k++) {
      let x = start + k * cycle;
      items.forEach((s, i) => {
        if (x < crawlRight && x + widths[i] > crawlLeft) {
          crawl += `<text x="${x}" y="${baseline}" font-family="Montserrat" font-weight="800" font-size="${itemFont.size}"
                          fill="#ffffff">${escapeXml(s)}</text>`;
        }
        x += widths[i] + bulletGap;
        crawl += `<circle cx="${x}" cy="${y + bandH / 2}" r="${bulletR}" fill="${props.accent}"/>`;
        x += bulletGap;
      });
    }
  }
  const hx = x0 + headW / 2;
  const hy = y + bandH / 2;
  const headBox = props.headline && pop > 0.001
    ? `<g transform="translate(${hx} ${hy}) scale(${Math.min(1.06, pop)}) translate(${-hx} ${-hy})">
        <rect x="${x0}" y="${y}" width="${headW}" height="${bandH}" fill="${props.accent}"/>
        <text x="${hx}" y="${hy + headSize * 0.36}" text-anchor="middle" font-family="Montserrat" font-weight="900"
              font-size="${headSize}" letter-spacing="${2 * u}" fill="#ffffff">${escapeXml(props.headline)}</text>
      </g>`
    : "";
  return svg(ctx, `
    <defs>
      <clipPath id="band"><rect x="${clipLeft}" y="${y}" width="${Math.max(0, clipRight - clipLeft)}" height="${bandH}"/></clipPath>
      <clipPath id="crawl"><rect x="${crawlLeft}" y="${y}" width="${Math.max(0, crawlRight - crawlLeft)}" height="${bandH}"/></clipPath>
    </defs>
    ${clipRight - clipLeft > 0.5 ? `<g clip-path="url(#band)">
      <rect x="${x0}" y="${y}" width="${bandW}" height="${bandH}" fill="${props.background}" fill-opacity="0.92"/>
      <rect x="${x0}" y="${y}" width="${bandW}" height="${4 * u}" fill="${props.accent}"/>
      <g clip-path="url(#crawl)">${crawl}</g>
      ${headBox}
    </g>` : ""}`);
}

// logo-reveal — a bundled template (spec §11 G-44): a full card on which an
// accent bar sweeps across the centre, wiping in a logo image (or, with none,
// a text mark) that settles to size, and a tagline fading up.
export const meta = {
  name: "Logo reveal",
  durationInFrames: 120,
};

export const schema = {
  logo:       { type: "asset",  default: null, kind: "image" },
  mark:       { type: "string", default: "FRAME JOB" },
  tagline:    { type: "string", default: "Edit at the speed of thought" },
  background: { type: "color",  default: "#0b0b10" },
  accent:     { type: "color",  default: "#ff5a36" },
};

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const D = ctx.durationInFrames;
  const safeW = ctx.width * 0.9;
  const safeH = ctx.height * 0.9;
  const cx = ctx.width / 2;
  const cy = ctx.height / 2;
  let markW;
  let markH;
  let content;
  const markSize = fitText(props.mark, safeW * 0.8, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 200 * u });
  if (props.logo) {
    markW = safeW * 0.5;
    markH = Math.min(safeH * 0.32, markW);
    content = `<image href="${asset(props.logo)}" x="${cx - markW / 2}" y="${cy - markH / 2}" width="${markW}"
                      height="${markH}" preserveAspectRatio="xMidYMid meet"/>`;
  } else {
    markW = measureText(props.mark, { family: "Montserrat", size: markSize, weight: 900 }).width;
    markH = markSize * 0.74;
    content = `<text x="${cx}" y="${cy + markH / 2}" text-anchor="middle" font-family="Montserrat" font-weight="900"
                     font-size="${markSize}" fill="#ffffff">${escapeXml(props.mark)}</text>`;
  }
  const barH = markH + 80 * u;
  const barW = 16 * u;
  const from = cx - markW / 2 - 50 * u;
  const to = cx + markW / 2 + 50 * u;
  const sweep = interpolate(frame, [4, 34], [0, 1], { easing: Easing.inOutCubic, clamp: true });
  const barX = from + (to - from) * sweep;
  const barFade = interpolate(frame, [34, 44], [1, 0], { clamp: true });
  const settle = interpolate(frame, [4, 54], [1.06, 1], { easing: Easing.outCubic, clamp: true });
  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
  const scale = settle + 0.04 * out;
  const alpha = 1 - out;
  const tagIn = interpolate(frame, [34, 56], [0, 1], { easing: Easing.outCubic, clamp: true });
  const tagSize = props.tagline ? Math.min(44 * u, fitText(props.tagline, safeW * 0.8,
    { family: "Montserrat", weight: 800 }, { min: 10 * u, max: 44 * u })) : 0;
  const tagY = cy + markH / 2 + 50 * u + tagSize * 0.9 + (1 - tagIn) * 20 * u;
  const revealW = Math.max(0, barX - (from - 10 * u));
  return svg(ctx, `
    <defs>
      <clipPath id="wipe"><rect x="${from - 10 * u}" y="${cy - barH / 2}" width="${revealW}" height="${barH}"/></clipPath>
    </defs>
    <g opacity="${alpha}" transform="translate(${cx} ${cy}) scale(${scale}) translate(${-cx} ${-cy})">
      ${revealW > 0.5 ? `<g clip-path="url(#wipe)">${content}</g>` : ""}
      ${props.tagline ? `<text x="${cx}" y="${tagY}" text-anchor="middle" font-family="Montserrat" font-weight="800"
            font-size="${tagSize}" fill="#d8d8e0" fill-opacity="${tagIn}">${escapeXml(props.tagline)}</text>` : ""}
    </g>
    ${barFade > 0 && sweep > 0 ? `<rect x="${barX - barW / 2}" y="${cy - barH / 2}" width="${barW}" height="${barH}"
          fill="${props.accent}" fill-opacity="${barFade}"/>` : ""}`, { background: props.background });
}

