  const groupW = Math.max(wA, wB) + (props.bell ? 24 * u + bellD : 0);
  const margin = 70 * u;
  const cy = props.position === "top" ? safeY + margin + btnH / 2
    : props.position === "center" ? ctx.height / 2
    : safeY + safeH - margin - btnH / 2 - 40 * u;
  const gx = ctx.width / 2 - groupW / 2;
  const bx = gx;
  const bcx = bx + btnW / 2;
