  const scale = pop * (1 - 0.15 * out);
  return svg(ctx, `
    <g opacity="${1 - out}" transform="translate(${gcx} ${cy}) scale(${scale}) translate(${-gcx} ${-cy})">
      ${button}${bell}${cursor}
    </g>`);
