// TEMPORARY: variant renders for a person to look at; deleted before hand-off.
mod common;
use graphic::rasterize;
use std::fs;
fn dump(stem: &str, tag: &str, frame: i64, size: (u32, u32), over: serde_json::Value) {
    let module = common::module(stem);
    let mut props = module.defaults();
    for (k, v) in over.as_object().unwrap() { props[k] = v.clone(); }
    let d = module.meta()["durationInFrames"].as_i64().unwrap();
    let ctx = common::ctx(frame, 30.0, d, size.0, size.1);
    let (svg, w) = graphic::svg(&module, frame, &props, &ctx, 250).unwrap_or_else(|e| panic!("{stem} {}", e.message));
    assert!(w.is_empty(), "{stem} {tag}: {w:?}");
    let stride = size.0 as usize * 4;
    let mut out = vec![0u8; stride * size.1 as usize];
    let r = rasterize(&common::shared(), &svg, size.0, size.1, &mut out, stride).unwrap();
    assert!(r.is_empty(), "{stem} {tag}: {r:?}");
    let rgb: Vec<u8> = out.chunks_exact(4).flat_map(|p| { let un = 255 - p[3] as u32; let o = |s: u8, b: u32| (s as u32 + (b * un + 127) / 255).min(255) as u8; [o(p[2], 0x6e), o(p[1], 0x6e), o(p[0], 0x74)] }).collect();
    let dir = "/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/8f8ab556-be01-4c5e-8a57-e4a4085a4571/scratchpad/variants";
    fs::create_dir_all(dir).unwrap();
    let f = fs::File::create(format!("{dir}/{stem}-{tag}-{}x{}-{frame}.png", size.0, size.1)).unwrap();
    let mut e = png::Encoder::new(std::io::BufWriter::new(f), size.0, size.1);
    e.set_color(png::ColorType::Rgb); e.set_depth(png::BitDepth::Eight);
    e.write_header().unwrap().write_image_data(&rgb).unwrap();
}
#[test]
fn variants() {
    let l = (1920, 1080); let p = (1080, 1920);
    let j = serde_json::json!;
    dump("social-popup", "like", 60, l, j!({}));
    dump("social-popup", "comment", 60, l, j!({"kind": "comment", "text": "This is exactly the cut I needed for my channel, thanks!"}));
    dump("social-popup", "share", 60, p, j!({"kind": "share", "position": "top-left"}));
    for g in ["camera", "bubble", "note", "globe"] { dump("handle-tag", g, 60, l, j!({"glyph": g, "position": "top-right"})); }
    dump("keyboard-keys", "dark", 45, l, j!({"theme": "dark", "keys": "ctrl+opt+up", "position": "center"}));
    dump("keyboard-keys", "word", 45, p, j!({"keys": "cmd+shift+enter", "position": "top"}));
    dump("window-frame", "light", 75, l, j!({"style": "window", "theme": "light"}));
    dump("arrow-highlight", "box", 60, l, j!({"shape": "box"}));
    dump("arrow-highlight", "arrow", 60, p, j!({"shape": "arrow", "x": 0.2, "y": 0.8}));
    dump("step-badge", "br", 45, l, j!({"position": "bottom-right", "number": 12}));
    dump("countdown", "flash", 302, l, j!({}));
    dump("countdown", "up", 100, p, j!({"from": 0, "to": 90, "format": "h:mm:ss", "ring": false}));
    dump("progress-bar", "top", 80, p, j!({"position": "top"}));
    dump("subscribe-button", "center", 40, l, j!({"position": "center", "bell": false}));
    dump("logo-reveal", "asset", 70, l, j!({"logo": "red.png"}));
    dump("chapter-card", "long", 70, p, j!({"number": 12, "title": "A much longer chapter title here"}));
    dump("line-chart", "one", 100, l, j!({"values": "5"}));
    dump("donut-chart", "zero", 100, l, j!({"values": "0, 0"}));
    dump("gauge", "degenerate", 100, l, j!({"min": 0, "max": 0, "value": 0}));
}
